INSERT INTO `messages` VALUES (95, 17, 1, 'bot', NULL, 'Supresso Assistant', 'bot_handoff_94_1790146921', 'Baik, saya telah mengalihkan percakapan ini ke staf Customer Service kami. Mohon tunggu sebentar, staf kami akan segera membalas pesan Anda.', 'text', '{\"is_bot\":true,\"is_handoff\":true,\"inbound_msg_id\":94}', 'sent', 0, '2026-09-23 07:02:01', '2026-09-23 07:02:01');
