INSERT INTO `messages` VALUES (100, 18, 1, 'bot', NULL, 'Supresso Assistant', 'bot_rule_99_1790147022', '🛒 *Checkout Assistance*\nWe are here to assist you with your checkout and payment. Please select an option:', 'text', '{\"is_bot\":true,\"matched_keyword\":\"checkout\",\"inbound_msg_id\":99,\"options\":[{\"label\":\"Kris+ Voucher\",\"value\":\"Kris+ Voucher\"},{\"label\":\"Checkout Button\",\"value\":\"Checkout Button\"},{\"label\":\"Payment Methods\",\"value\":\"Payment Methods\"},{\"label\":\"Order Issue\",\"value\":\"Order Issue\"},{\"label\":\"Main Menu\",\"value\":\"MENU\"},{\"label\":\"Chat with CS\",\"value\":\"CS\"}]}', 'sent', 0, '2026-09-23 07:03:42', '2026-09-23 07:03:42');
INSERT INTO `messages` VALUES (101, 18, 1, 'visitor', NULL, 'tes chat bot', 'msg_mudrbfle_ajqk4i9', 'Kris+ Voucher', 'text', NULL, 'sent', 0, '2026-09-23 07:03:45', '2026-09-23 07:03:45');
INSERT INTO `messages` VALUES (102, 18, 1, 'bot', NULL, 'Supresso Assistant', 'bot_rule_101_1790147025', 'Redeem your Kris+ vouchers for an extra 20% OFF* exclusive on our website!\n\nT&C*:\n1. This SGD 10 promo code must be redeemed by 30 June 2025.\n2. No extensions are allowed.\n3. Valid for redemption online at Supresso official website (supresso.com).\n4. Promo codes are valid only for full-priced items and cannot be applied to discounted or promotional items, it is only valid for transactions above SGD 30.\n5. Orders above SGD 30 will be entitled to free shipping.\n6. Limited to 1 redemption per order (one-time usage only).\n\nShould you have anymore questions, do not hesitate to contact us!', 'text', '{\"is_bot\":true,\"matched_keyword\":\"kris+ voucher\",\"inbound_msg_id\":101,\"options\":[{\"label\":\"Checkout Button\",\"value\":\"Checkout Button\"},{\"label\":\"Payment Methods\",\"value\":\"Payment Methods\"},{\"label\":\"Main Menu\",\"value\":\"MENU\"},{\"label\":\"Chat with CS\",\"value\":\"CS\"}]}', 'sent', 0, '2026-09-23 07:03:45', '2026-09-23 07:03:45');
INSERT INTO `messages` VALUES (103, 18, 1, 'visitor', NULL, 'tes chat bot', 'msg_mudri0h6_v3z1c20', 'checkout', 'text', NULL, 'sent', 0, '2026-09-23 07:08:51', '2026-09-23 07:08:51');
INSERT INTO `messages` VALUES (104, 18, 1, 'bot', NULL, 'Supresso Assistant', 'bot_rule_103_1790147331', '🛒 *Checkout Assistance*\nWe are here to assist you with your checkout and payment. Please select an option:', 'text', '{\"is_bot\":true,\"matched_keyword\":\"checkout\",\"inbound_msg_id\":103,\"options\":[{\"label\":\"Kris+ Voucher\",\"value\":\"Kris+ Voucher\"},{\"label\":\"Checkout Button\",\"value\":\"Checkout Button\"},{\"label\":\"Payment Methods\",\"value\":\"Payment Methods\"},{\"label\":\"Order Issue\",\"value\":\"Order Issue\"},{\"label\":\"Main Menu\",\"value\":\"MENU\"},{\"label\":\"Chat with CS\",\"value\":\"CS\"}]}', 'sent', 0, '2026-09-23 07:08:51', '2026-09-23 07:08:51');
INSERT INTO `messages` VALUES (105, 18, 1, 'visitor', NULL, 'tes chat bot', 'msg_mudri5vq_ovkz3cg', 'kris+', 'text', NULL, 'sent', 0, '2026-09-23 07:08:58', '2026-09-23 07:08:58');
INSERT INTO `messages` VALUES (106, 18, 1, 'bot', NULL, 'Supresso Assistant', 'bot_rule_105_1790147338', 'Redeem your Kris+ vouchers for an extra 20% OFF* exclusive on our website!\n\nT&C*:\n1. This SGD 10 promo code must be redeemed by 30 June 2025.\n2. No extensions are allowed.\n3. Valid for redemption online at Supresso official website (supresso.com).\n4. Promo codes are valid only for full-priced items and cannot be applied to discounted or promotional items, it is only valid for transactions above SGD 30.\n5. Orders above SGD 30 will be entitled to free shipping.\n6. Limited to 1 redemption per order (one-time usage only).\n\nShould you have anymore questions, do not hesitate to contact us!', 'text', '{\"is_bot\":true,\"matched_keyword\":\"kris+\",\"inbound_msg_id\":105,\"options\":[{\"label\":\"Checkout Button\",\"value\":\"Checkout Button\"},{\"label\":\"Payment Methods\",\"value\":\"Payment Methods\"},{\"label\":\"Main Menu\",\"value\":\"MENU\"},{\"label\":\"Chat with CS\",\"value\":\"CS\"}]}', 'sent', 0, '2026-09-23 07:08:58', '2026-09-23 07:08:58');
INSERT INTO `messages` VALUES (107, 19, 1, 'visitor', NULL, 'inta test', 'msg_mudrjruw_csonf3o', 'Order', 'text', NULL, 'sent', 0, '2026-09-23 07:10:13', '2026-09-23 07:10:13');
INSERT INTO `messages` VALUES (108, 19, 1, 'bot', NULL, 'Supresso Assistant', 'bot_rule_107_1790147413', '📦 *Order Assistance*\nWe are here to assist you with your order. Please choose an option below:', 'text', '{\"is_bot\":true,\"matched_keyword\":\"order\",\"inbound_msg_id\":107,\"options\":[{\"label\":\"Order Status\",\"value\":\"Order Status\"},{\"label\":\"Cancellation\",\"value\":\"Cancellation\"},{\"label\":\"Return Policy\",\"value\":\"Return Policy\"},{\"label\":\"Main Menu\",\"value\":\"MENU\"},{\"label\":\"Chat with CS\",\"value\":\"CS\"}]}', 'sent', 0, '2026-09-23 07:10:13', '2026-09-23 07:10:13');
INSERT INTO `messages` VALUES (109, 19, 1, 'visitor', NULL, 'inta test', 'msg_mudrkerf_iasf3l0', 'Order Status', 'text', NULL, 'sent', 0, '2026-09-23 07:10:42', '2026-09-23 07:10:42');
INSERT INTO `messages` VALUES (110, 19, 1, 'bot', NULL, 'Supresso Assistant', 'bot_rule_109_1790147442', 'Orders are typically fulfilled within 2-3 business days. Once your order has been fulfilled, a shipping confirmation email and WhatsApp message will be sent with your tracking information.\n\nShould you have anymore questions, do not hesitate to contact us!', 'text', '{\"is_bot\":true,\"matched_keyword\":\"order status\",\"inbound_msg_id\":109,\"options\":[{\"label\":\"Cancellation\",\"value\":\"Cancellation\"},{\"label\":\"Return Policy\",\"value\":\"Return Policy\"},{\"label\":\"Main Menu\",\"value\":\"MENU\"},{\"label\":\"Chat with CS\",\"value\":\"CS\"}]}', 'sent', 0, '2026-09-23 07:10:42', '2026-09-23 07:10:42');
INSERT INTO `messages` VALUES (111, 19, 1, 'visitor', NULL, 'inta test', 'msg_mudrknry_0nzhwvd', 'Cancellation', 'text', NULL, 'sent', 0, '2026-09-23 07:10:54', '2026-09-23 07:10:54');
INSERT INTO `messages` VALUES (112, 19, 1, 'bot', NULL, 'Supresso Assistant', 'bot_rule_111_1790147454', 'We process and complete orders as quickly as possible. If you have any modification requests or cancellation, please contact our Customer Support team immediately with your Order ID.\n\nShould you have anymore questions, do not hesitate to contact us!', 'text', '{\"is_bot\":true,\"matched_keyword\":\"cancellation\",\"inbound_msg_id\":111,\"options\":[{\"label\":\"Order Status\",\"value\":\"Order Status\"},{\"label\":\"Return Policy\",\"value\":\"Return Policy\"},{\"label\":\"Main Menu\",\"value\":\"MENU\"},{\"label\":\"Chat with CS\",\"value\":\"CS\"}]}', 'sent', 0, '2026-09-23 07:10:54', '2026-09-23 07:10:54');
INSERT INTO `messages` VALUES (113, 19, 1, 'visitor', NULL, 'inta test', 'msg_mudrkzk7_xlalg2l', 'Return Policy', 'text', NULL, 'sent', 0, '2026-09-23 07:11:09', '2026-09-23 07:11:09');
INSERT INTO `messages` VALUES (114, 19, 1, 'bot', NULL, 'Supresso Assistant', 'bot_rule_113_1790147469', 'All forms of order errors and damage to goods during delivery are not our responsibility. Please ensure you inspect your package upon arrival and record an unboxing video.\n\nFor verified defective items, please reach out to our Customer Support team with your order number and unboxing video for resolution.\n\nShould you have anymore questions, do not hesitate to contact us!', 'text', '{\"is_bot\":true,\"matched_keyword\":\"return policy\",\"inbound_msg_id\":113,\"options\":[{\"label\":\"Order Status\",\"value\":\"Order Status\"},{\"label\":\"Cancellation\",\"value\":\"Cancellation\"},{\"label\":\"Main Menu\",\"value\":\"MENU\"},{\"label\":\"Chat with CS\",\"value\":\"CS\"}]}', 'sent', 0, '2026-09-23 07:11:09', '2026-09-23 07:11:09');
INSERT INTO `messages` VALUES (115, 19, 1, 'visitor', NULL, 'inta test', 'msg_mudrr4ym_5lkw075', 'how to buy', 'text', NULL, 'sent', 0, '2026-09-23 07:15:57', '2026-09-23 07:15:57');
INSERT INTO `messages` VALUES (116, 19, 1, 'bot', NULL, 'Supresso Assistant', 'bot_rule_115_1790147757', 'Supresso Coffee is available through several official channels. Where would you like to shop?', 'text', '{\"is_bot\":true,\"matched_keyword\":\"how to buy\",\"inbound_msg_id\":115,\"options\":[{\"label\":\"Buy from Shopee\",\"value\":\"Buy from Shopee\"},{\"label\":\"Buy from Lazada\",\"value\":\"Buy from Lazada\"},{\"label\":\"Buy from Website\",\"value\":\"Buy from Website\"},{\"label\":\"Main Menu\",\"value\":\"MENU\"},{\"label\":\"Chat with CS\",\"value\":\"CS\"}]}', 'sent', 0, '2026-09-23 07:15:57', '2026-09-23 07:15:57');
INSERT INTO `messages` VALUES (117, 19, 1, 'visitor', NULL, 'inta test', 'msg_mudrxubh_82y61xu', 'Buy from Shopee', 'text', NULL, 'sent', 0, '2026-09-23 07:21:10', '2026-09-23 07:21:10');
INSERT INTO `messages` VALUES (118, 19, 1, 'bot', NULL, 'Supresso Assistant', 'bot_rule_117_1790148070', 'Visit our official Supresso store on Shopee Singapore for exciting flash deals, cashback vouchers, and fast delivery!\n\nShopee: https://shopee.sg/supressocoffee', 'text', '{\"is_bot\":true,\"matched_keyword\":\"buy from shopee\",\"inbound_msg_id\":117,\"options\":[{\"label\":\"Buy from Lazada\",\"value\":\"Buy from Lazada\"},{\"label\":\"Buy from Website\",\"value\":\"Buy from Website\"},{\"label\":\"Main Menu\",\"value\":\"MENU\"},{\"label\":\"Chat with CS\",\"value\":\"CS\"}]}', 'sent', 0, '2026-09-23 07:21:10', '2026-09-23 07:21:10');
